"""Image validation uses generated bytes only; no files or external images."""
from io import BytesIO
import struct
import zlib

from PIL import Image
import pytest

from page_manager.errors import AppError
from page_manager import images


def encoded(format='PNG', size=(7, 5)):
    stream = BytesIO()
    Image.new('RGB', size, 'navy').save(stream, format=format)
    return stream.getvalue()


@pytest.mark.parametrize('format,mime', [('PNG', 'image/png'), ('JPEG', 'image/jpeg')])
def test_valid_local_image_is_returned_exactly_without_rewriting(format, mime):
    raw = encoded(format)
    assert images.validate_image(raw, mime) == (raw, mime)
    assert images.validate_image(bytearray(raw), mime.upper() + '; fixture=value') == (raw, mime)


@pytest.mark.parametrize('raw,mime', [
    (b'', 'image/png'), (None, 'image/png'), ('local-path.png', 'image/png'),
    (b'https://example.test/image.png', 'image/png'), (b'<svg></svg>', 'image/png'),
    (b'not an image', 'image/jpeg'), (encoded('PNG'), 'image/jpeg'),
    (encoded('JPEG'), 'image/png'), (encoded('PNG'), 'text/html'),
    (encoded('PNG'), None), (encoded('GIF'), 'image/png'),
])
def test_invalid_payload_format_or_mime_is_rejected(raw, mime):
    with pytest.raises(AppError) as error:
        images.validate_image(raw, mime)
    assert error.value.code == 'invalid_image' and error.value.status_code == 422


@pytest.mark.parametrize('format,mime', [('PNG', 'image/png'), ('JPEG', 'image/jpeg')])
@pytest.mark.parametrize('removed', [1, 2, 8, 12])
def test_truncated_image_container_is_rejected_even_when_pixels_decode(format, mime, removed):
    with pytest.raises(AppError):
        images.validate_image(encoded(format)[:-removed], mime)


@pytest.mark.parametrize('format,mime', [('PNG', 'image/png'), ('JPEG', 'image/jpeg')])
def test_trailing_nonimage_data_is_rejected(format, mime):
    with pytest.raises(AppError):
        images.validate_image(encoded(format) + b'<html>fixture payload</html>', mime)


def test_animated_png_is_not_accepted_as_single_avatar_or_cover():
    stream = BytesIO()
    Image.new('RGB', (5, 5), 'red').save(stream, format='PNG', save_all=True,
        append_images=[Image.new('RGB', (5, 5), 'blue')], duration=100, loop=0)
    with pytest.raises(AppError):
        images.validate_image(stream.getvalue(), 'image/png')


def test_compressed_dimension_bomb_is_rejected_before_pixel_loading(monkeypatch):
    def chunk(kind, payload):
        return struct.pack('>I', len(payload)) + kind + payload + struct.pack('>I', zlib.crc32(kind + payload) & 0xffffffff)
    raw = b'\x89PNG\r\n\x1a\n' + chunk(b'IHDR', struct.pack('>IIBBBBB', 20_000_001, 1, 8, 2, 0, 0, 0))
    raw += chunk(b'IDAT', zlib.compress(b'\0\0\0\0')) + chunk(b'IEND', b'')
    loaded = []
    monkeypatch.setattr(Image.Image, 'load', lambda *args, **kwargs: loaded.append(True))
    with pytest.raises(AppError):
        images.validate_image(raw, 'image/png')
    assert not loaded


def test_pixel_limit_boundary_and_encoded_byte_limit(monkeypatch):
    monkeypatch.setattr(images, 'MAX_IMAGE_PIXELS', 4)
    raw = encoded(size=(2, 2))
    assert images.validate_image(raw, 'image/png')[0] == raw
    with pytest.raises(AppError):
        images.validate_image(encoded(size=(3, 2)), 'image/png')
    monkeypatch.setattr(images, 'MAX_IMAGE_BYTES', len(raw) - 1)
    with pytest.raises(AppError):
        images.validate_image(raw, 'image/png')


def test_png_chunk_corruption_is_rejected():
    raw = bytearray(encoded())
    index = raw.index(b'IDAT') + 4
    raw[index] ^= 0xff
    with pytest.raises(AppError):
        images.validate_image(raw, 'image/png')
